param(
    [string]$OutputPath = ""
)

$ErrorActionPreference = "Stop"

$rootDir = Split-Path -Parent $PSScriptRoot
if (-not $OutputPath -or [string]::IsNullOrWhiteSpace($OutputPath)) {
    $OutputPath = Join-Path $rootDir "MapApiSurface.baseline.json"
}

# The map API generator writes the WIT document during the build, so the surface is regenerated by building
# Realm.MapAPI with the property that asks it to record a baseline instead of verifying one. It is deliberately an
# explicit command: accepting a change to the import surface is an author's decision, never a build's.
$mapApiProj = Join-Path $rootDir "Realm.MapAPI\Realm.MapAPI.csproj"

& dotnet build "$mapApiProj" -c Debug "-p:RealmMapApiSurfaceBaselineOut=$OutputPath" --no-incremental -v q -nologo
if ($LASTEXITCODE -ne 0) {
    throw "Failed to regenerate the map API surface baseline through Realm.MapAPI"
}

if (-not (Test-Path $OutputPath)) {
    throw "The build did not write a map API surface baseline to $OutputPath"
}

Write-Host "Wrote the map API surface baseline to $OutputPath"
